CREATE VIRTUAL TABLE t2 USING fts4(order=DESC); BEGIN; WITH RECURSIVE seq(i) AS (VALUES(0) UNION ALL SELECT i+1 FROM seq WHERE i<9999) INSERT INTO t2(docid, content) SELECT i, CASE i % 10 WHEN 0 THEN 'one zero' WHEN 1 THEN 'two zero' WHEN 2 THEN 'three zero' WHEN 3 THEN 'four zero' WHEN 4 THEN 'five zero' WHEN 5 THEN 'six zero' WHEN 6 THEN 'seven zero' WHEN 7 THEN 'eight zero' WHEN 8 THEN 'nine zero' WHEN 9 THEN 'ten zero' END FROM seq; COMMIT; INSERT INTO t2(t2) VALUES('optimize');